#include "statistics.hpp"
int main(){try{require(mean({1,2,3,4})==2.5&&quantile({1,2,3,4},.5)==2.5,"Midpoint median failure");require(std::abs(quantile({1,2,3,4},.9)-3.7)<1e-12&&std::abs(quantile({1,2,3,4},.95)-3.85)<1e-12,"Tail quantile convention failure");std::array<std::vector<double>,3>x{{{2,4,6,8},{4,8,12,16},{1,2,3,4}}};auto b=paired(x,202610157801ULL),again=paired(x,202610157801ULL);require(b[0].ratio==4&&b[0].lo==4&&b[0].hi==4&&b[1].ratio==2&&b[2].ratio==2,"Exact constant paired ratios failure");for(size_t i=0;i<3;i++)require(b[i].lo==again[i].lo&&b[i].hi==again[i].hi,"Bootstrap reproducibility failure");size_t rejected=0;auto bad=[&](auto fn){bool failed=false;try{fn();}catch(const std::exception&){failed=true;}require(failed,"Negative statistical input accepted");rejected++;};bad([&]{quantile({},.5);});bad([&]{quantile({1,2},-1);});bad([&]{mean({1,INFINITY});});auto y=x;y[1].pop_back();bad([&]{paired(y,1);});y=x;y[2][0]=0;bad([&]{paired(y,1);});std::cout<<"PASS midpoint/tail quantiles, exact paired contrasts, reproducibility and "<<rejected<<" rejected invalid inputs\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
